package com.markethub.common.exception;
import com.markethub.common.api.ApiResponse; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiResponse<Void>> validation(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+": "+x.getDefaultMessage()).orElse("Request validation failed");return ResponseEntity.badRequest().body(ApiResponse.failure(new ApiResponse.ApiError("VALIDATION_ERROR",m)));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ApiResponse<Void>> badRequest(IllegalArgumentException e){return ResponseEntity.badRequest().body(ApiResponse.failure(new ApiResponse.ApiError("BAD_REQUEST",e.getMessage())));} @ExceptionHandler(Exception.class) ResponseEntity<ApiResponse<Void>> unexpected(Exception e){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(ApiResponse.failure(new ApiResponse.ApiError("INTERNAL_ERROR","An unexpected error occurred")));} }